"use strict";(self.webpackChunkhalt_website=self.webpackChunkhalt_website||[]).push([["74631"],{44083(e){e.exports=JSON.parse('{"tag":{"label":"GI Health","permalink":"/docs/tags/gi-health","allTagsPath":"/docs/tags","count":11,"items":[{"id":"guinea-pigs/illnesses-and-conditions/bloat-in-guinea-pigs","title":"Bloat in Guinea Pigs","description":"Bloat, also known as Gastric Dilatation and Volvulus (GDV), is a sudden, life-threatening condition that can affect guinea pigs. It occurs when the stomach fills with gas and, in some cases, twists on itself (volvulus), cutting off blood supply to the stomach and other organs. This is a severe medical emergency that requires immediate veterinary intervention. Understanding the signs and acting quickly can be the difference between life and death.","permalink":"/docs/guinea-pigs/illnesses-and-conditions/bloat-in-guinea-pigs"},{"id":"Rabbits/illnesses-and-conditions/coccidia-in-rabbits","title":"Coccidia in Rabbits","description":"A comprehensive guide to coccidiosis in rabbits \u2014 causes, symptoms, diagnosis, treatment, and prevention of this common parasitic infection.","permalink":"/docs/Rabbits/illnesses-and-conditions/coccidia-in-rabbits"},{"id":"Gerbils/illnesses-and-conditions/common-health-issues","title":"Common Health Issues in Gerbils","description":"An overview of the most common health issues affecting pet gerbils, including respiratory infections, scent gland tumors, tail slip, and Tyzzer\'s disease.","permalink":"/docs/Gerbils/illnesses-and-conditions/common-health-issues"},{"id":"Hamsters/illnesses-and-conditions/common-health-issues","title":"Common Health Issues in Hamsters","description":"An overview of the most common health issues affecting pet hamsters, including the critical emergency of wet tail, respiratory infections, and common tumors.","permalink":"/docs/Hamsters/illnesses-and-conditions/common-health-issues"},{"id":"Ferrets/health-and-wellness/gi-health","title":"Gastrointestinal (GI) Health in Ferrets","description":"A guide to gastrointestinal (GI) health in ferrets, covering their unique digestive system and common issues like foreign body obstructions, vomiting, diarrhea, and ECE.","permalink":"/docs/Ferrets/health-and-wellness/gi-health"},{"id":"Hedgehogs/health-and-wellness/gi-health","title":"Gastrointestinal (GI) Health in Hedgehogs","description":"A guide to gastrointestinal (GI) health in hedgehogs, covering their unique dietary needs as insectivores and the common causes of digestive upset.","permalink":"/docs/Hedgehogs/health-and-wellness/gi-health"},{"id":"Mice/health-and-wellness/gi-health","title":"Gastrointestinal (GI) Health in Mice","description":"A guide to gastrointestinal (GI) health in mice, covering common issues like diarrhea and the serious threat of Tyzzer\'s disease, and emphasizing the importance of a stable diet and stress-free environment.","permalink":"/docs/Mice/health-and-wellness/gi-health"},{"id":"Rabbits/illnesses-and-conditions/gi-issues-in-rabbits","title":"GI Issues in Rabbits","description":"For rabbit owners, understanding and preventing gastrointestinal (GI) issues is paramount to ensuring the health and happiness of their beloved pets. Rabbits have delicate digestive systems, and...","permalink":"/docs/Rabbits/illnesses-and-conditions/gi-issues-in-rabbits"},{"id":"guinea-pigs/health-and-wellness/guineapigpoop","title":"Guinea Pig Poop","description":"Guinea pigs have sensitive digestive systems, and looking at their poop is the best way to quickly determine how your guinea pig\'s system is functioning. It\'s also one of the reasons why it\'s so...","permalink":"/docs/guinea-pigs/health-and-wellness/guineapigpoop"},{"id":"Rabbits/health-and-wellness/home-health-care-for-your-rabbit","title":"Home Health Care for Your Rabbit","description":"Caring for a rabbit can be a deeply rewarding experience, bringing joy and companionship to your home. These intelligent and social creatures, capable of living up to 12\u201315 years, thrive with proper care and attention [1]. Understanding their unique needs \u2014 from diet to dental health and disease prevention \u2014 is crucial for ensuring a long and happy life for your furry friend. This guide walks you through essential aspects of home health care for your rabbit.","permalink":"/docs/Rabbits/health-and-wellness/home-health-care-for-your-rabbit"},{"id":"Hamsters/illnesses-and-conditions/wet-tail","title":"Wet Tail in Hamsters","description":"An essential guide to wet tail in hamsters, a serious and often fatal diarrheal disease, explaining its causes, signs, and the critical need for immediate veterinary action.","permalink":"/docs/Hamsters/illnesses-and-conditions/wet-tail"}],"unlisted":false}}')}}]);